#ifndef ZEPHYR_LIB_LINEAR_RANGE_H_
#define ZEPHYR_LIB_LINEAR_RANGE_H_

#include <zephyr/types.h>

struct linear_range {
    int base;
    int step;
    int count;
};

void linear_range_create(struct linear_range *lr, int base, int step, int count);
int linear_range_get_value(const struct linear_range *lr, int index, int *value);
int linear_range_get_index(const struct linear_range *lr, int value, int *index);
int linear_range_get_max_value(const struct linear_range *lr, int *value);

#endif /* ZEPHYR_LIB_LINEAR_RANGE_H_ */
